Translate the following MS C++ code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original MS C++ code you have to translate:
<original_code>
#include <iostream>
#include <string>
#include <algorithm>
#include <cmath>
#include <iomanip>
#include <map>
#include <queue>
#include <set>
#include <stack>
using namespace std;

long long round_to_nearest(long long num, long long den) {
    long long q = num / den;
    long long r = num % den;
    if (r > den - r) q += 1;
    return q;
}

int main() {
    long long x, y, n;
    cin >> x >> y >> n;
    long long best_num = 0, best_den = 1;
    for (long long i = 1; i <= n; ++i) {
        long long temp = round_to_nearest(x * i, y);
        long long left = best_den * (x * i - temp * y);
        long long right = i * (x * best_den - y * best_num);
        if (abs(left) < abs(right)) {
            best_num = temp;
            best_den = i;
        }
    }
    cout << best_num << "/" << best_den << endl;
    return 0;
}
</original_code>
